document.querySelector('#language-select').addEventListener('change',async event=>{
 const nextLanguage=event.target.value,previous=language();
 if(!['es','en'].includes(nextLanguage)||nextLanguage===previous)return;
 event.target.disabled=true;
 try{
   const response=await fetch(nextLanguage==='en'?'course.en.json':'course.json',{cache:'no-cache'});
   if(!response.ok)throw new Error('Catalogue unavailable');
   const next=await response.json();if(next.id!==course.id||next.modules?.length!==32)throw new Error('Incompatible catalogue');
   course=next;setLanguage(nextLanguage);document.documentElement.lang=nextLanguage;
   const url=new URL(location.href);url.searchParams.set('lang',nextLanguage);history.replaceState(null,'',url);
   try{localStorage.setItem(LANG_KEY,nextLanguage);}catch{}
   render(false,false);
 }catch(error){event.target.value=previous;toast(error.message);}finally{event.target.disabled=false;}
});

